presets.css:
/* ========== A. 主题变量（与当前界面默认一致；改这里最快） ========== */
.chat-thread {
  --dress-chat-bg-overlay: transparent;

  /* 顶栏文字颜色等基础变量 */
  --dress-header-title-color: var(--black);
  --dress-header-title-size: 15px;
  --dress-header-title-weight: 500;
  --dress-header-icon-color: var(--ink);

  /* ★ 我方气泡（强制粉色，圆角：14px 14px 4px 14px） */
  --dress-bubble-me-bg: #f5acbb !important;
  --dress-bubble-me-bg-gradient: linear-gradient(#f5acbb, #f5acbb) !important; 
  --dress-bubble-me-fg: #ffffff !important;
  --dress-bubble-me-border: none;
  --dress-bubble-me-shadow: 0 2px 10px rgba(0, 0, 0, 0.06);
  --dress-bubble-me-radius: 14px 14px 4px 14px !important; 

  /* ★ 对方气泡（圆角：4px 14px 14px 14px） */
  --dress-bubble-them-bg: #fff;
  --dress-bubble-them-fg: var(--ink);
  --dress-bubble-them-border: none;
  --dress-bubble-them-shadow: 0 2px 12px rgba(0, 0, 0, 0.05);
  --dress-bubble-them-radius: 4px 14px 14px 14px !important; 

  /* 输入胶囊基础变量 (在L区单独精细控制) */
  --dress-compose-bar-bg: transparent !important;
  --dress-compose-bar-fg: var(--ink);
  --dress-compose-bar-radius: 0px;
  --dress-compose-bar-border: none !important;
  --dress-compose-bar-shadow: none !important;
  --dress-compose-bar-blur: 0px !important;

  --dress-timestamp-color: var(--soft);
  --dress-scroll-pad-x: 14px;
}

html[data-theme="dark"] .chat-thread {
  --dress-header-title-color: #f0f0f0;
  --dress-header-icon-color: #f0f0f0;

  /* 暗黑模式下也强制保持粉色 */
  --dress-bubble-me-bg: #f5acbb !important;
  --dress-bubble-me-bg-gradient: linear-gradient(#f5acbb, #f5acbb) !important;
  --dress-bubble-me-fg: #ffffff !important;

  --dress-bubble-them-bg: #2e2e2e;
  --dress-bubble-them-fg: #efefef;
  --dress-bubble-them-shadow: 0 4px 16px rgba(0, 0, 0, 0.22);

  --dress-compose-bar-bg: transparent !important;
  --dress-compose-bar-border: none !important;
  --dress-compose-bar-shadow: none !important;

  --dress-timestamp-color: rgba(255, 255, 255, 0.55);
}

/* ========== B. 壳 / 滚动 ========== */
.chat-thread { background: var(--dress-chat-bg-overlay); }
.chat-thread-scroll {}

/* ========== C. 顶栏 (真·贴边实心通栏 + 底部圆角) ========== */

/* 1. 强制外层容器撑满顶部，去掉所有悬浮边距 */
.chat-thread-top {
  padding: 0 !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  width: 100% !important;
}

/* 2. 胶囊变通栏 (高度和底板完全锁定，不再更改) */
.chat-thread-pill {
  width: 100% !important;
  max-width: 100% !important;
  margin: 0 !important;
  border-radius: 0 0 16px 16px !important; 
  border: none !important;
  background-color: #ffffff !important; 
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.06) !important; 
  padding: calc(env(safe-area-inset-top, 20px) + 8px) 16px 26px 16px !important; 
  height: auto !important;
  box-sizing: border-box !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}
html[data-theme="dark"] .chat-thread-pill {
  background-color: #2a2a2a !important; 
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.35) !important;
}

/* ★ 3. 顶栏按钮自定义图标 (仅限日间模式) */

/* 返回按钮 */
.chat-back {
  background-image: url("https://imgbed.heliar.top/i/Jw_SFQ2HnPJ1FMtj_IMG_5438.png") !important;
  background-size: 24px auto !important;
  background-position: center left !important;
  background-repeat: no-repeat !important;
}
.chat-back * { opacity: 0 !important; }

/* 心声按钮 (往右移) */
.chat-thread-head-xinsheng { 
  transform: translateX(-4px) !important; 
  background-image: url("https://imgbed.heliar.top/i/nIqQ0ddtrrZ1vcIB_IMG_5440.png") !important;
  background-size: 26px auto !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
}
.chat-thread-head-xinsheng * { opacity: 0 !important; }

/* 更多/设置按钮 */
.chat-thread-head-more { 
  background-image: url("https://imgbed.heliar.top/i/dcs2A2Pka4AhSP2Q_IMG_5439.png") !important;
  background-size: 26px auto !important;
  background-position: center right !important;
  background-repeat: no-repeat !important;
}
.chat-thread-head-more * { opacity: 0 !important; }

/* 暗黑模式下恢复系统默认顶栏图标 */
html[data-theme="dark"] .chat-back,
html[data-theme="dark"] .chat-thread-head-xinsheng,
html[data-theme="dark"] .chat-thread-head-more {
  background-image: none !important;
}
html[data-theme="dark"] .chat-back *,
html[data-theme="dark"] .chat-thread-head-xinsheng *,
html[data-theme="dark"] .chat-thread-head-more * {
  opacity: 1 !important;
}


/* ★ 顶栏中间区域 */
.chat-thread-center {
  position: relative !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: center !important;
}
.chat-thread-center h2 {
  color: var(--dress-header-title-color);
  font-size: 17px !important; 
  font-weight: 900 !important; 
  line-height: 1 !important;
  margin: 0 !important; 
}

/* ★ 核心重构：名字下方的小尾巴 */
.chat-thread-center::after {
  content: "+370";
  position: absolute;
  top: 100%; 
  left: 50%;
  transform: translateX(-50%); 
  margin-top: 14px; 

  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", sans-serif !important;
  font-weight: 600 !important;
  font-size: 11px !important;
  color: #000000;
  line-height: 14px !important;

  width: 100px; 
  box-sizing: border-box;
  padding-left: 64px; 
  text-align: left;

  background-image: 
    url("https://imgbed.heliar.top/i/fCMiz8nJMdZpmH1h_IMG_5448.png"), 
    url("https://i.postimg.cc/0jCBSV1Q/IMG-5400.png"); 

  background-position: 
    43px center, 
    2px center;  

  background-size: 
    contain,    
    auto 12px;  

  background-repeat: no-repeat;
}
html[data-theme="dark"] .chat-thread-center::after {
  color: #ffffff; 
}

/* ========== D. 消息行 / 头像 / 昵称 ========== */
.chat-msg {}
.chat-msg.is-me {}
.chat-msg.is-them {}

/* ★ 气泡外层容器：为了让时间戳和贴纸能绝对定位，必须加 relative */
.chat-msg-body {
  position: relative !important;
  overflow: visible !important;
}

/* ★ 对方气泡整体左移 */
.chat-msg.is-them .chat-msg-body {
  transform: translateX(-10px) !important; 
}

/* ★ 我方气泡整体右移 */
.chat-msg.is-me .chat-msg-body {
  transform: translateX(10px) !important; 
}

/* ★ 我方气泡左侧、时间戳上方的贴纸 */
.chat-msg.is-me .chat-msg-body::before {
  content: "";
  position: absolute;
  right: calc(100% + 4px); 
  bottom: 12px; 
  width: 22px; 
  height: 22px; 
  background-image: url("https://imgbed.heliar.top/i/8JQrUjilbupZxHKf_IMG_5446.png"); 
  background-size: contain;
  background-repeat: no-repeat;
  background-position: bottom right;
  pointer-events: none; 
}

.chat-swipe-host, .chat-swipe-content, .chat-longpress-host {}

/* ★ 双方头像大小缩小为 38px，并强制切成圆形 */
.chat-ava {
  width: 38px !important;
  height: 38px !important;
  border-radius: 50% !important; 
}
.chat-ava img, .chat-ava-sm img {
  border-radius: 50% !important;
}

/* ★ 对方头像：左移(-8px) 且 上移(-12px) */
.chat-msg.is-them .chat-ava {
  transform: translate(-8px, -12px) !important; 
  position: relative !important;
  overflow: visible !important; 
}

/* ★ 对方头像框 (比例收紧到 120%) */
.chat-msg.is-them .chat-ava::after {
  content: "";
  position: absolute;
  top: -10%;
  left: -10%;
  width: 120%;
  height: 120%;
  background-image: url("https://imgbed.heliar.top/i/1X1zbJdlrqtx25ox_IMG_5442.png"); 
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  pointer-events: none; 
  z-index: 10;
}

/* ★ 我方头像：右移(8px) */
.chat-msg.is-me .chat-ava {
  transform: translateX(8px) !important; 
}

/* ★ 名字变黑（暗黑模式变白） */
.chat-msg-name {
  font-size: 11px;
  opacity: 1 !important; 
  color: #000000 !important; 
}
html[data-theme="dark"] .chat-msg-name {
  color: #ffffff !important; 
}

/* ★ 对方昵称整体往左移 */
.chat-msg.is-them .chat-msg-name {
  padding-left: 2px !important; 
}

/* ★ 对方昵称前面的贴纸 */
.chat-msg.is-them .chat-msg-name::before {
  content: "";
  display: inline-block;
  width: 42px; 
  height: 14px; 
  background-image: url("https://imgbed.heliar.top/i/8vTjJELIalPjHdm2_IMG_5445.png"); 
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center left;
  vertical-align: middle; 
  margin-right: 6px; 
  margin-top: -2px; 
}

/* ========== E. 气泡 ========== */
.chat-bubble { line-height: 1.55; }
.chat-bubble-primary {}

/* ==========================================
   ★ 终极清道夫：消灭原实线，画上新虚线
   ========================================== */

/* 1. 物理消灭气泡内可能存在的横线标签或空元素 */
.chat-msg:has(.chat-bubble-trans-inline) hr {
  display: none !important;
}
.chat-msg:has(.chat-bubble-trans-inline) .chat-bubble *:empty:not(img):not(svg):not(br) {
  display: none !important;
}

/* 2. 抹除可能存在的父级边框颜色 */
.chat-msg:has(.chat-bubble-trans-inline) .chat-bubble > div {
  border-color: transparent !important;
}

/* 3. 在翻译文字上，干干净净地画出我们的浅灰虚线 */
.chat-bubble-trans-inline {
  color: #ec94a6 !important; 
  display: block !important;

  /* 强制覆盖并画出虚线 */
  border-top: 1px dashed rgba(0, 0, 0, 0.15) !important;

  /* ★ 让虚线往上移：减小 margin-top，增大 padding-top */
  margin-top: 2px !important;
  padding-top: 8px !important;
}
html[data-theme="dark"] .chat-bubble-trans-inline {
  border-top: 1px dashed rgba(255, 255, 255, 0.25) !important;
}

.chat-bubble-trans-chip {}
.chat-bubble-trans-chip-label {}
.chat-bubble.has-block-badge, .chat-msg-block-badge {}

/* ========== F. 时间戳 / 灰字通知 ========== */

/* ★ 对方时间标：放在气泡右边 */
.chat-msg.is-them .chat-msg-time,
.chat-msg.is-them .chat-msg-timestamp {
  position: absolute !important;
  left: 100% !important; 
  bottom: 0px !important; 
  margin-left: 4px !important; 
  white-space: nowrap !important; 
}

/* ★ 我方时间标：放在气泡左边 */
.chat-msg.is-me .chat-msg-time,
.chat-msg.is-me .chat-msg-timestamp {
  position: absolute !important;
  right: 100% !important; 
  bottom: 0px !important; 
  margin-right: 4px !important; 
  white-space: nowrap !important; 
}

.chat-thread-notice-wrap {}
.chat-thread-notice {}
.chat-thread-notice.is-tap {}
.chat-thread-notice-hint {}

/* ========== G. 引用 / 撤回 ========== */
.chat-qq-quote {}
.chat-qq-quote.is-tap {}
.chat-qq-quote-name {}
.chat-qq-quote-text {}
.chat-recall-wrap {}
.chat-recall-row {}
.chat-recall-text {}
.chat-recall-view {}

/* ========== H. 语音 ========== */
.chat-msg.has-voice .chat-msg-body {}

/* ★ 语音气泡形状同步为普通气泡形状 */
.chat-msg.is-them .puff-voice-pill {
  border-radius: 4px 14px 14px 14px !important;
}
.chat-msg.is-me .puff-voice-pill {
  border-radius: 14px 14px 4px 14px !important;
}

.puff-voice-waves, .puff-voice-wave {}
.puff-voice-glyph {}
.puff-voice-dur {}
.puff-voice-note {}
.puff-voice-note-body {}
.puff-voice-note-tr {}

/* ========== I. 表情 / 图片 ========== */
.chat-msg.has-sticker .chat-msg-body, .chat-msg.has-image .chat-msg-body {}
.chat-bubble-sticker {}
.chat-msg.is-me .chat-bubble-sticker {}
.puff-photo {}

/* ========== J. 反应 ========== */
.chat-msg-reactions {}
.chat-reaction-chip {}
.chat-reaction-chip-emoji {}
.chat-reaction-chip-meta {}

/* ========== K. 卡片消息 ========== */
.chat-msg.has-transfer .chat-msg-body, .chat-msg.has-red-envelope .chat-msg-body {}
.chat-msg.has-gift .chat-msg-body {}
.chat-msg.has-diary-share .chat-msg-body, .chat-msg.has-forum-share .chat-msg-body {}
.chat-msg.has-listen-together .chat-msg-body {}
.chat-msg.has-location .chat-msg-body, .chat-msg.has-takeout .chat-msg-body {}
.chat-msg.has-shop-order .chat-msg-body {}
.puff-transfer {}
.puff-gift {}
.puff-diary-share {}
.puff-forum-share {}
.puff-call-end-msg, .puff-call-end-card {}
.chat-offline-ticket-wrap, .chat-offline-ticket {}
.chat-offline-ticket-k, .chat-offline-ticket-text, .chat-offline-ticket-link {}

/* ========== L. 输入胶囊 (高级分离重构版) ========== */

/* 1. 底部外层变成通栏白底 */
.chat-compose {
  background-color: #ffffff !important;
  border-top: 1px solid rgba(0, 0, 0, 0.05) !important;
  padding: 8px 12px calc(env(safe-area-inset-bottom, 20px) + 8px) !important;
  position: relative !important;
}
html[data-theme="dark"] .chat-compose {
  background-color: #1a1a1a !important;
  border-top: 1px solid rgba(255, 255, 255, 0.05) !important;
}

/* 2. 中间层变透明，作为绝对定位的基准 */
.chat-compose-bar {
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
  margin: 0 !important; 
  width: 100% !important;
  padding: 0 !important;
  display: flex !important;
  align-items: center !important;
  position: relative !important;
}

/* 3. ★ 核心：输入框本体变成 #fafafa 浅灰色胶囊 */
.chat-compose-input {
  background-color: #fafafa !important; 
  border-radius: 18px !important; 

  /* 右侧留出 40px 的白底空白，用来放外面的发送/回复按钮 */
  margin: 0 40px 0 0 !important; 

  /* 左侧留白给隐形菜单按钮，右侧留白给内部的语音按钮 */
  padding: 6px 36px 6px 40px !important; 

  min-height: 36px !important; 
  height: auto !important;
  line-height: 20px !important;
  border: none !important;
  flex-grow: 1 !important; 
}
html[data-theme="dark"] .chat-compose-input {
  background-color: #2e2e2e !important;
}

/* 彻底隐藏输入消息的占位文字 */
.chat-compose-input::placeholder {
  color: transparent !important;
}
.chat-compose-input::-webkit-input-placeholder {
  color: transparent !important;
}

/* 4. ★ 左侧菜单按钮：悬浮在胶囊左端，用同色圆完美隐身 */
.chat-compose-bar > :first-child:not(.chat-compose-input) {
  position: absolute !important;
  left: 4px !important; 
  width: 32px !important;
  height: 32px !important;
  z-index: 10 !important; 
  background: transparent !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
}
/* 画一个 #fafafa 的实心圆盖住图标，完美融入胶囊背景 */
.chat-compose-bar > :first-child:not(.chat-compose-input)::after {
  content: '';
  position: absolute;
  top: 0; left: 0; width: 100%; height: 100%;
  background-color: #fafafa !important;
  border-radius: 50%;
  z-index: 20; /* 盖在图标上面 */
  pointer-events: none !important; /* 让点击穿透遮罩 */
}
html[data-theme="dark"] .chat-compose-bar > :first-child:not(.chat-compose-input)::after {
  background-color: #2e2e2e !important;
}

/* 5. ★ 右侧按钮精准分离 & 替换图标 */

/* 语音按钮：绝对定位在输入框内部 */
.chat-compose-icon.is-voice {
  position: absolute !important;
  right: 44px !important; 
  width: 32px !important;
  height: 32px !important;
  z-index: 10 !important;

  /* 替换为自定义语音图标 */
  background-image: url("https://imgbed.heliar.top/i/c7BGJM5dP7PaHoyi_IMG_5436.png") !important;
  background-size: 26px auto !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  background-color: transparent !important;
}
.chat-compose-icon.is-voice * { opacity: 0 !important; }

/* 发送 & 回复按钮：绝对定位在输入框外部 */
.chat-compose-icon.is-send,
.chat-compose-icon.is-send.ready,
.chat-compose-icon.is-reply {
  position: absolute !important;
  right: 4px !important; 
  width: 32px !important;
  height: 32px !important;
  z-index: 10 !important;

  /* 替换为自定义发送/回复图标 */
  background-image: url("https://imgbed.heliar.top/i/MI2NZxwmvgY3ag6O_IMG_5437.png") !important;
  background-size: 26px auto !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  background-color: transparent !important;
}
.chat-compose-icon.is-send *, 
.chat-compose-icon.is-reply * { opacity: 0 !important; }

/* 暗黑模式下恢复系统默认底栏图标 */
html[data-theme="dark"] .chat-compose-icon.is-voice,
html[data-theme="dark"] .chat-compose-icon.is-send,
html[data-theme="dark"] .chat-compose-icon.is-reply {
  background-image: none !important;
}
html[data-theme="dark"] .chat-compose-icon.is-voice *,
html[data-theme="dark"] .chat-compose-icon.is-send *,
html[data-theme="dark"] .chat-compose-icon.is-reply * {
  opacity: 1 !important;
}
